# ===========================================================================
# 2. VALORES CALCULADOS POR TU ALGORITMO (w y b finales)
# ===========================================================================
resultados_propios = {
    "R1": {"w": 1.8798, "b": 1.3196, "status": "Converge"},
    "R2": {"w": 1.9595, "b": 0.6696, "status": "Converge"},
    "R3": {"w": -488429935991654144.0, "b": -6625569054270102.0, "status": "DIVERGE"},
    "R4": {"w": -76579544911184526683088994959360.0, "b": -568367841218133626047034294272.0, "status": "DIVERGE"}
}

# ===========================================================================
# 3. GENERACIÓN DE GRÁFICOS
# ===========================================================================
analisis = [
    (regresion1, "Horas de Estudio", "blue", "R1"),
    (regresion2, "Horas de Sueño", "green", "R2"),
    (regresion3, "Asistencia %", "orange", "R3"),
    (regresion4, "Ejercicios Resueltos", "red", "R4")
]

fig, axes = plt.subplots(2, 2, figsize=(14, 12))
fig.suptitle("Reporte Final de Regresiones (Valores del Algoritmo GD)", fontsize=16, fontweight='bold')

for i, (datos, nombre, color, key) in enumerate(analisis):
    ax = axes[i // 2, i % 2]
    
    # Extraer X e Y
    x_vals = [d[0] for d in datos]
    y_vals = [d[1] for d in datos]
    
    # Valores del algoritmo
    w_alg = resultados_propios[key]["w"]
    b_alg = resultados_propios[key]["b"]
    status = resultados_propios[key]["status"]

    # Definir línea de regresión
    x_line = np.linspace(min(x_vals), max(x_vals), 100)
    y_line = w_alg * x_line + b_alg
    
    # Graficar puntos reales
    ax.scatter(x_vals, y_vals, color=color, alpha=0.5, label='Datos de Estudiantes')
    
    # Graficar línea del algoritmo
    ax.plot(x_line, y_line, color='black', linewidth=2, label=f'Predicción GD ({status})')
    
    # Ajustar escala solo para los que convergen para que se vea la línea
    # En los divergentes, dejamos que la escala explote para mostrar la magnitud
    if status == "Converge":
        ax.set_ylim(0, 25) # Notas de 0 a 20
    else:
        # Para los divergentes, ponemos una nota de advertencia
        ax.text(0.5, 0.9, f"¡DIVERGENCIA CRÍTICA!\nw={w_alg:.1e}", 
                transform=ax.transAxes, color='red', fontsize=10, fontweight='bold', ha='center')

    ax.set_title(f"Regresión {i+1}: {nombre}")
    ax.set_xlabel(nombre)
    ax.set_ylabel("Nota Final")
    ax.legend(loc='lower right')
    ax.grid(True, linestyle='--', alpha=0.3)



# ===========================================================================
# SECCIÓN MODIFICADA PARA MOSTRAR LA ECUACIÓN EN LA GRÁFICA
# ===========================================================================

for i, (datos, nombre, color, key) in enumerate(analisis):
    ax = axes[i // 2, i % 2]
    
    # Extraer X e Y para los puntos
    x_vals = [d[0] for d in datos]
    y_vals = [d[1] for d in datos]
    
    # Valores que te botó el algoritmo
    w_alg = resultados_propios[key]["w"]
    b_alg = resultados_propios[key]["b"]
    status = resultados_propios[key]["status"]

    # Crear la línea de la función
    x_line = np.linspace(min(x_vals), max(x_vals), 100)
    y_line = w_alg * x_line + b_alg
    
    # 1. Dibujar los puntos reales
    ax.scatter(x_vals, y_vals, color=color, alpha=0.5, label='Datos Reales')
    
    # 2. Dibujar la línea de la regresión
    ax.plot(x_line, y_line, color='black', linewidth=2, label='Modelo GD')
    
    # 3. INSERTAR TEXTO DE LA FUNCIÓN EN LA IMAGEN (Solo para R1 y R2 que convergen)
    if status == "Converge":
        # Ponemos el texto en la parte superior izquierda del recuadro
        ecuacion = f"f(x) = {w_alg:.4f}x + ({b_alg:.4f})"
        ax.text(0.05, 0.92, ecuacion, transform=ax.transAxes, 
                fontsize=11, fontweight='bold', color='black',
                bbox=dict(facecolor='white', alpha=0.8, edgecolor='gray'))
        ax.set_ylim(0, 25) 
    else:
        # Nota de divergencia para R3 y R4
        ax.text(0.5, 0.5, "DIVERGENCIA", transform=ax.transAxes, 
                color='red', fontsize=14, fontweight='bold', ha='center')

    ax.set_title(f"Regresión {i+1}: {nombre}")
    ax.set_xlabel(nombre)
    ax.set_ylabel("Nota Final")
    ax.legend(loc='lower right')
    ax.grid(True, linestyle='--', alpha=0.3)


plt.tight_layout(rect=[0, 0.03, 1, 0.95])
print("Generando gráficas basadas en tus resultados...")
plt.show()